using Microsoft.EntityFrameworkCore;using QuanLyKho.Data;using QuanLyKho.DTOs;using QuanLyKho.Models;namespace QuanLyKho.Services;public sealed class ProductService{readonly ApplicationDbContext db;public ProductService(ApplicationDbContext db)=>this.db=db;public async Task<IReadOnlyList<ProductDto>> GetAllAsync(string? search){var q=db.Products.AsNoTracking().Include(x=>x.Category).AsQueryable();if(!string.IsNullOrWhiteSpace(search)){var k=search.Trim();q=q.Where(x=>x.ProductCode.Contains(k)||x.ProductName.Contains(k));}return await q.OrderBy(x=>x.ProductName).Select(x=>new ProductDto(x.Id,x.ProductCode,x.ProductName,x.CategoryId,x.Category!.CategoryName,x.Unit,x.Price,x.StockQuantity)).ToListAsync();}public async Task<ProductDto> GetByIdAsync(int id)=>await db.Products.AsNoTracking().Include(x=>x.Category).Where(x=>x.Id==id).Select(x=>new ProductDto(x.Id,x.ProductCode,x.ProductName,x.CategoryId,x.Category!.CategoryName,x.Unit,x.Price,x.StockQuantity)).FirstOrDefaultAsync()??throw new KeyNotFoundException("Không tìm thấy sản phẩm.");public async Task<ProductDto> CreateAsync(ProductRequest r){var code=r.ProductCode.Trim().ToUpperInvariant();if(await db.Products.AnyAsync(x=>x.ProductCode==code))throw new InvalidOperationException("Mã sản phẩm đã tồn tại.");if(!await db.Categories.AnyAsync(x=>x.Id==r.CategoryId))throw new InvalidOperationException("Danh mục không tồn tại.");var e=new Product{ProductCode=code,ProductName=r.ProductName.Trim(),CategoryId=r.CategoryId,Unit=r.Unit.Trim(),Price=r.Price,StockQuantity=r.StockQuantity};db.Products.Add(e);await db.SaveChangesAsync();return await GetByIdAsync(e.Id);}public async Task<ProductDto> UpdateAsync(int id,ProductRequest r){var e=await db.Products.FindAsync(id)??throw new KeyNotFoundException("Không tìm thấy sản phẩm.");var code=r.ProductCode.Trim().ToUpperInvariant();if(await db.Products.AnyAsync(x=>x.Id!=id&&x.ProductCode==code))throw new InvalidOperationException("Mã sản phẩm đã tồn tại.");e.ProductCode=code;e.ProductName=r.ProductName.Trim();e.CategoryId=r.CategoryId;e.Unit=r.Unit.Trim();e.Price=r.Price;e.StockQuantity=r.StockQuantity;await db.SaveChangesAsync();return await GetByIdAsync(id);}public async Task DeleteAsync(int id){var e=await db.Products.FindAsync(id)??throw new KeyNotFoundException("Không tìm thấy sản phẩm.");if(await db.ReceiptDetails.AnyAsync(x=>x.ProductId==id)||await db.IssueDetails.AnyAsync(x=>x.ProductId==id))throw new InvalidOperationException($"Không thể xóa {e.ProductName} vì sản phẩm đã có lịch sử nhập/xuất.");db.Products.Remove(e);await db.SaveChangesAsync();}}